"use client"

import { KeyboardEvent } from "react"

type AvatarProps = {
  name: string
  src?: string
}

export function Avatar({ name, src }: AvatarProps) {
  const initials = name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]!.toUpperCase())
    .join("")

  const size = "var(--atlas-spacing-12)"

  if (src) {
    return (
      <img
        src={src}
        alt={name}
        style={{
          inlineSize: size,
          blockSize: size,
          borderRadius: "var(--atlas-radius-full)",
          objectFit: "cover",
        }}
      />
    )
  }

  return (
    <div
      style={{
        inlineSize: size,
        blockSize: size,
        borderRadius: "var(--atlas-radius-full)",
        backgroundColor: "var(--atlas-primary-subtle)",
        color: "var(--atlas-primary)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "var(--atlas-font-size-lg)",
        fontWeight: "var(--atlas-font-weight-semibold)",
      }}
      aria-hidden="true"
    >
      {initials}
    </div>
  )
}

export type ThemeChoice = "light" | "dark" | "system"

const THEME_OPTIONS: { value: ThemeChoice; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "system", label: "System" },
]

type ThemeSegmentedControlProps = {
  value: ThemeChoice
  onChange: (value: ThemeChoice) => void
}

export function ThemeSegmentedControl({ value, onChange }: ThemeSegmentedControlProps) {
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const currentIndex = THEME_OPTIONS.findIndex((option) => option.value === value)
    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      event.preventDefault()
      const next = THEME_OPTIONS[(currentIndex + 1) % THEME_OPTIONS.length]
      onChange(next.value)
    } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      event.preventDefault()
      const prev = THEME_OPTIONS[(currentIndex - 1 + THEME_OPTIONS.length) % THEME_OPTIONS.length]
      onChange(prev.value)
    }
  }

  return (
    <div
      role="radiogroup"
      aria-label="Theme"
      onKeyDown={handleKeyDown}
      style={{
        display: "flex",
        gap: "var(--atlas-spacing-1)",
        padding: "var(--atlas-spacing-1)",
        backgroundColor: "var(--atlas-background-muted)",
        borderRadius: "var(--atlas-radius-lg)",
      }}
    >
      {THEME_OPTIONS.map((option) => {
        const checked = option.value === value
        return (
          <div
            key={option.value}
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            onClick={() => onChange(option.value)}
            style={{
              flex: 1,
              textAlign: "center",
              paddingBlock: "var(--atlas-spacing-2)",
              paddingInline: "var(--atlas-spacing-3)",
              borderRadius: "var(--atlas-radius-md)",
              fontSize: "var(--atlas-text-body-sm)",
              fontWeight: "var(--atlas-font-weight-medium)",
              cursor: "pointer",
              backgroundColor: checked ? "var(--atlas-surface-raised)" : "transparent",
              color: checked ? "var(--atlas-foreground)" : "var(--atlas-foreground-muted)",
              boxShadow: checked ? "var(--atlas-shadow-sm)" : "none",
            }}
          >
            {option.label}
          </div>
        )
      })}
    </div>
  )
}

